 public static void Install(KeepawayMatch m){if(m.chaosField!=null)return;const string folder="TruckKeepaway";m.arenaX=32;m.arenaZ=18;var slate=SportsEventAuthoring.Mat(folder,"Arena slate",new Color(.08f,.17f,.23f),.4f);var ivory=SportsEventAuthoring.Mat(folder,"Arena white",new Color(.84f,.91f,.89f));var dark=SportsEventAuthoring.Mat(folder,"Obstacle navy",new Color(.045f,.1f,.13f));var mud=SportsEventAuthoring.Mat(folder,"Mud patch",new Color(.2f,.15f,.09f),.3f);var puddle=SportsEventAuthoring.Mat(folder,"Slippery puddle",new Color(.08f,.26f,.36f),.9f);var rail=SportsEventAuthoring.Contact(folder,"Barrier contact",.25f,.3f);var contact=SportsEventAuthoring.Contact(folder,"Arena contact",.7f,.08f);
 foreach(var t in UnityEngine.Object.FindObjectsByType<Transform>(FindObjectsInactive.Include)){if(t.name=="Keepaway arena")t.localScale=new Vector3(66,.6f,38);else if(t.name=="Side boundary"){t.position=new Vector3(Mathf.Sign(t.position.x)*32.5f,.6f,0);t.localScale=new Vector3(.6f,1.2f,38);}else if(t.name=="End boundary"){t.position=new Vector3(0,.6f,Mathf.Sign(t.position.z)*18.5f);t.localScale=new Vector3(66,1.2f,.6f);}else if(t.name=="Rounded cover bollard"||t.name=="Broad escape ramp")UnityEngine.Object.DestroyImmediate(t.gameObject);}
 var field=m.gameObject.AddComponent<KeepawayChaos>();m.chaosField=field;field.match=m;field.solidProps=new Transform[8];field.ramps=new Transform[4];field.patches=new Transform[6];field.movable=new Rigidbody[8];field.sweepers=new Rigidbody[2];field.sheep=new KeepawaySheep[16];
 for(int i=0;i<8;i++){var g=SportsEventAuthoring.Box("Seeded solid crate "+i,new Vector3((i%4-1.5f)*11,.6f,i<4?-7:7),new Vector3(3,1.2f,2.5f),dark,rail);field.solidProps[i]=g.transform;var visual=new GameObject("Installed crate presentation");visual.transform.SetParent(g.transform,false);visual.transform.localScale=new Vector3(1/3f,1/1.2f,1/2.5f);Art(visual,"Assets/IndieKit/Crates and Barrels/Prefabs/Non-Destructible/crate_01.prefab",dark);g.GetComponent<Renderer>().enabled=false;
 var moving=SportsEventAuthoring.Box("Movable tire stack "+i,new Vector3((i%4-1.5f)*8,.7f,i<4?-11:11),new Vector3(1.5f,1.4f,1.5f),dark,rail);var body=moving.AddComponent<Rigidbody>();body.mass=3;body.angularDamping=.45f;body.maxLinearVelocity=20;body.maxAngularVelocity=8;field.movable[i]=body;var render=new GameObject("Installed tire presentation");render.transform.SetParent(moving.transform,false);render.transform.localScale=new Vector3(1/1.5f,1/1.4f,1/1.5f);Art(render,"Assets/RoadPropsPack/URP/Prefabs/TireStacked01_URP.prefab",dark);moving.GetComponent<Renderer>().enabled=false;
 }
 for(int i=0;i<4;i++)field.ramps[i]=SportsEventAuthoring.Box("Seeded escape ramp "+i,new Vector3(i%2==0?-19:19,.45f,i<2?0:13),new Vector3(5,.35f,6),ivory,contact).transform;
 for(int i=0;i<6;i++)field.patches[i]=SportsEventAuthoring.Box("Surface patch "+i,new Vector3(i%3*18-18,.018f,i<3?-12:12),new Vector3(6,.025f,5),i%2==0?mud:puddle).transform;
 for(int i=0;i<2;i++){var g=SportsEventAuthoring.Box("Telegraphed rotating sweeper "+i,new Vector3(i==0?-9:9,.65f,0),new Vector3(6,.45f,.55f),ivory,rail);var b=g.AddComponent<Rigidbody>();b.isKinematic=true;field.sweepers[i]=b;var ring=new GameObject("Sweeper warning perimeter").AddComponent<LineRenderer>();ring.useWorldSpace=true;ring.sharedMaterial=SportsEventAuthoring.Mat(folder,"Hazard amber",new Color(1,.6f,.04f));ring.positionCount=49;ring.startWidth=ring.endWidth=.1f;for(int k=0;k<=48;k++){float a=k*Mathf.PI*2/48;ring.SetPosition(k,g.transform.position+new Vector3(Mathf.Sin(a)*3.4f,-.61f,Mathf.Cos(a)*3.4f));}}
 var sheepPrefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/TruckCheeseRolling/Prefabs/ExplosiveSheep.prefab");for(int i=0;i<16;i++){var g=(GameObject)PrefabUtility.InstantiatePrefab(sheepPrefab);PrefabUtility.UnpackPrefabInstance(g,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);g.name="Wandering SheepV5 "+i;var old=g.GetComponent<CheeseSheep>();if(old.warning!=null)old.warning.SetActive(false);UnityEngine.Object.DestroyImmediate(old);var body=g.GetComponent<Rigidbody>();if(body==null)body=g.AddComponent<Rigidbody>();body.isKinematic=true;var item=g.AddComponent<KeepawaySheep>();item.arena=field;item.body=body;item.index=i;field.sheep[i]=item;g.SetActive(false);}
 m.obstacles=field.solidProps.Select(t=>t.GetComponent<Collider>()).Concat(field.ramps.Select(t=>t.GetComponent<Collider>())).Concat(field.sweepers.Select(t=>t.GetComponent<Collider>())).ToArray();
 m.cabViews=new SportsEventCamera[4];for(int i=0;i<4;i++){m.cabViews[i]=SportsEventAuthoring.Camera("Keepaway driver seat "+i);m.cabViews[i].view.enabled=false;SportsChaosAuthoring.Cab(m.cabViews[i].view,folder,i);foreach(var t in m.trucks[i].visuals.GetComponentsInChildren<Transform>(true))t.gameObject.layer=22+i;var label=m.identities[i].gameObject.AddComponent<SportsPerCameraBillboard>();label.excludedLayer=22+i;m.identities[i].gameObject.layer=22+i;}
 m.broadcast.view.cullingMask=~(15<<26);m.broadcast.Pose(new Vector3(0,1,0),new Vector3(0,42,-19),60,true);var fit=m.broadcast.GetComponent<SportsCameraFit>();fit.arenaBounds=new Bounds(new Vector3(0,2,0),new Vector3(66,6,38));fit.topInset=.055f;fit.bottomInset=.065f;fit.sideInset=.01f;fit.Apply();field.weather=SportsChaosAuthoring.Weather(m,folder);var flare=SportsChaosAuthoring.Flare(folder);foreach(var fx in m.explosions)SportsChaosAuthoring.FixBlast(fx,flare);
