 for(int i=0;i<4;i++)m.menus.rows[i].GetComponent<RectTransform>().anchoredPosition=new Vector2(i%2==0?-350:350,100-i/2*160);
 var header=m.menus.header.transform.parent.GetComponent<RectTransform>();header.sizeDelta=new Vector2(1880,46);header.anchoredPosition=new Vector2(0,511);m.menus.header.fontSizeMax=24;m.menus.header.rectTransform.sizeDelta=new Vector2(1820,38);m.menus.standings.rectTransform.anchoredPosition=new Vector2(0,-461);m.menus.standings.rectTransform.sizeDelta=new Vector2(1800,65);m.menus.standings.alignment=TMPro.TextAlignmentOptions.Center;m.menus.standings.fontSizeMax=22;m.menus.status.rectTransform.anchoredPosition=new Vector2(0,-510);m.menus.status.fontSizeMax=21;
 foreach(var label in m.menus.viewTexts){label.rectTransform.sizeDelta=new Vector2(780,86);label.fontSizeMax=23;label.fontSizeMin=19;var backing=label.transform.parent.Find("View data backing").GetComponent<RectTransform>();backing.sizeDelta=new Vector2(800,106);}
 foreach(var label in m.menus.pages[4].GetComponentsInChildren<TMPro.TMP_Text>(true))if(label.name=="Rules and controls")label.text=m.Help;
 EditorUtility.SetDirty(m);Debug.Log("KEEP_CHAOS_SAVED seeded 66x38, SheepV5, shared weather, four cabs");
 }
 public static void Validate(){foreach(var path in new[]{KeepawayAuthoring.Scene,CabScene}){EditorSceneManager.OpenScene(path);var m=UnityEngine.Object.FindAnyObjectByType<KeepawayMatch>();if(m==null||m.chaosField==null||m.cabViews.Length!=4||m.chaosField.sheep.Length!=16||m.arenaX!=32||m.cabVariant!=(path==CabScene)||m.chaosField.weather.vendor.IsPermanent)throw new Exception("Keepaway chaos/variant saved references invalid: "+path);if(UnityEngine.Object.FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Length!=1)throw new Exception("Keepaway single listener required");foreach(var fx in m.explosions){var mat=fx.GetComponent<ParticleSystemRenderer>().sharedMaterial;if(mat.GetFloat("_Surface")!=1||mat.GetInt("_ZWrite")!=0||mat.GetTexture("_BaseMap")==null)throw new Exception("Keepaway explosion must be textured transparent");}Debug.Log("KEEP_VARIANT_SAVED_VALIDATED "+path);}}

}
